"""Bounded read-only schema probe through the existing loopback-only CF pattern."""
from pathlib import Path
import json
import os
import secrets
import shutil
import subprocess
import tempfile

root = Path('/var/www/business.roadrunners.run')
work = Path(tempfile.mkdtemp(prefix='business-home-metrics-', dir=root / '_codex'))
os.chmod(work, 0o755)
token = secrets.token_hex(32)
body = '<cfsetting showdebugoutput="false" requesttimeout="55"/><cfcontent type="application/json" reset="true"/><cfscript>\nreport={periods=[]};queries=deserializeJSON(toString(binaryDecode("","base64")));opts={datasource="runnerhub",timeout=5};\nfor(days in [7,30]){\n period={days=days,sources={}};\n params={days={value=days,cfsqltype="cf_sql_integer"}};\n for(sourceName in ["audience","ads","accounts","users"]){\n  started=getTickCount();item={loaded=false};\n  try {\n   transaction {\n    queryExecute("SET TRANSACTION READ ONLY",{},opts);\n    queryExecute("SET LOCAL statement_timeout=\'5s\'",{},opts);\n    q=queryExecute(queries[sourceName],params,opts);\n    item.loaded=q.recordCount==1;if(item.loaded)item.metrics=queryGetRow(q,1);\n   }\n  }catch(any e){item.error_type=e.type;if(structKeyExists(e,"sqlState"))item.sqlstate=e.sqlState;}\n  item.elapsed_ms=getTickCount()-started;period.sources[sourceName]=item;\n }\n arrayAppend(report.periods,period);\n}\nwriteOutput(serializeJSON(report));</cfscript>'
try:
    (work / '.htaccess').write_text('Require local\n')
    (work / 'Application.cfc').write_text(
        'component {this.name="' + work.name + '";this.datasource="runnerhub";'
        'boolean function onRequestStart(string target){'
        'if(!listFind("127.0.0.1,::1",cgi.remote_addr)||cgi.request_method!="POST"||'
        'compare(form.key ?: "","' + token + '")!=0){cfheader(statuscode=404);abort;}'
        'return true;}}')
    (work / 'run.cfm').write_text(body)
    for path in work.iterdir():
        os.chmod(path, 0o644)
    result = subprocess.run([
        'curl', '-sS', '--max-time', '53', '--resolve',
        'business.roadrunners.run:443:127.0.0.1', '-X', 'POST',
        '--data-urlencode', 'key=' + token,
        'https://business.roadrunners.run/_codex/' + work.name + '/run.cfm',
    ], capture_output=True, text=True, timeout=56)
    if result.returncode:
        raise RuntimeError('Schema request failed; transport output withheld')
    try:
        report = json.loads(result.stdout)
    except ValueError:
        raise RuntimeError('Schema request returned non-JSON; response withheld')
    report.update(read_only=True, runtime_files_changed=False, source_sha256='c1b53ac2a015b36e662d6cbd11684924931bbd0f75b28c1a716a2ac27d3f7b8a', cache_disabled=True)
finally:
    shutil.rmtree(work)
print(json.dumps(report, indent=2))
